import type { TransactionClient, TransactionRunner } from "../../../shared/domain/transaction.types.js";
import type { CreateEventInput, EventAuditService, EventRecord, EventStatus, EventType, ServiceRecord } from "./event.types.js";

// RF25 (ADR 0008): reuse an earlier event as the base for a new one. Only manual tasks and the
// allocated teams are copied; rule-generated tasks are regenerated by the engine on confirmation.

export type ReplicationSchedule = {
  eventDate: Date;
  endDate: Date | null;
};

export type TeamUnavailableReason = "NOT_FOUND" | "INACTIVE" | "SCHEDULE_CONFLICT";

export type TeamAvailability =
  | { available: true }
  | { available: false; reason: TeamUnavailableReason; conflictingEvent?: { id: string; name: string } };

// ----- Input of POST /events/:id/replicate -----

export type ReplicatedServiceInput = {
  serviceId: string;
  customLabel?: string | null;
};

// Omitted keys keep the source value; dueDate omitted means "recalculate", null means "no deadline".
export type ReplicatedTaskInput = {
  sourceTaskId: string;
  title?: string;
  description?: string | null;
  dueDate?: Date | null;
};

export type ReplicateEventInput = Omit<CreateEventInput, "createdById"> & {
  services: ReplicatedServiceInput[];
  tasks: ReplicatedTaskInput[];
  teamIds: string[];
};

// ----- Output of GET /events/:id/replication-preview -----

export type ReplicationWarning =
  | { code: "CLIENT_UNAVAILABLE" }
  | { code: "SERVICE_UNAVAILABLE"; serviceId: string; name: string };

export type ReplicationPreviewService = {
  serviceId: string;
  name: string;
  isCustom: boolean;
  customLabel: string | null;
};

export type ReplicationPreviewTask = {
  sourceTaskId: string;
  title: string;
  description: string | null;
  sourceStatus: string;
  originalDueDate: Date | null;
  dueDate: Date | null;
  dueDateInPast: boolean;
  assignedTeamId: string | null;
  selected: boolean;
};

export type ReplicationPreviewTeam = {
  teamId: string;
  name: string;
  specialty: string;
  available: boolean;
  reason: TeamUnavailableReason | null;
  conflictingEvent: { id: string; name: string } | null;
};

export type ReplicationPreview = {
  source: { id: string; name: string; status: EventStatus; eventDate: Date; endDate: Date | null };
  draft: {
    location: string;
    serviceType: EventType;
    guestsCount: number;
    observations: string | null;
    clientId: string | null;
    services: ReplicationPreviewService[];
  };
  warnings: ReplicationWarning[];
  tasks: ReplicationPreviewTask[];
  teams: ReplicationPreviewTeam[];
};

export type ReplicationTeamConflict = {
  teamId: string;
  reason: TeamUnavailableReason;
  conflictingEvent: { id: string; name: string } | null;
};

// ----- Ports (implemented by Prisma repositories and the Teams module, wired in event.factory) -----

export type CreateReplicaInput = CreateEventInput & {
  sourceEventId: string;
  services: { serviceId: string; customLabel: string | null }[];
};

export interface ReplicationEventStore {
  findById(id: string): Promise<EventRecord | null>;
  createReplica(input: CreateReplicaInput, tx: TransactionClient): Promise<EventRecord>;
}

// Applies the same validations as a regular creation (RN03, future date, active client).
export interface EventCreationPolicy {
  assertCanCreate(input: CreateEventInput): Promise<void>;
}

export interface ReplicationServiceCatalog {
  findById(id: string): Promise<ServiceRecord | null>;
}

export type ReplicationSourceTask = {
  id: string;
  title: string;
  description: string | null;
  dueDate: Date | null;
  status: string;
  assignedTeamId: string | null;
  sourceRuleId: string | null;
};

export type CreateReplicatedTaskInput = {
  eventId: string;
  title: string;
  description: string | null;
  dueDate: Date | null;
  assignedTeamId: string | null;
  assignedAt: Date | null;
  sourceRuleId: null;
  sourceTaskId: string;
};

export interface ReplicationTaskStore {
  // Non-deleted tasks of the event (the repository already filters soft-deleted rows).
  listByEvent(eventId: string): Promise<ReplicationSourceTask[]>;
  create(input: CreateReplicatedTaskInput, tx: TransactionClient): Promise<{ id: string }>;
}

export interface ReplicationTeamGateway {
  listTeamsByEvent(eventId: string): Promise<{ teamId: string }[]>;
  findTeam(teamId: string): Promise<{ id: string; name: string; specialty: string } | null>;
  checkAvailability(teamId: string, schedule: ReplicationSchedule): Promise<TeamAvailability>;
  assign(eventId: string, teamId: string, actorId: string, tx: TransactionClient): Promise<unknown>;
}

export type EventReplicationDependencies = {
  events: ReplicationEventStore;
  creationPolicy: EventCreationPolicy;
  catalog: ReplicationServiceCatalog;
  tasks: ReplicationTaskStore;
  teams: ReplicationTeamGateway;
  transactions: TransactionRunner;
  audit: EventAuditService;
  now?: () => Date;
};
